insert into public.products (name, slug, description, price, image_url, category, available, published, waitlist_open, release_code)
values
  ('Velocity Runner', 'velocity-runner', 'A precise balance of retro track lines and everyday comfort. Lightweight mesh meets a sculpted, responsive sole.', 168.00, 'https://images.unsplash.com/photo-1696954895451-701b481056d8?q=80&w=687&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'Running', true, true, true, 'SD / 001'),
  ('Studio Form 01', 'studio-form-01', 'An understated court silhouette with soft leather panels, considered proportions and a quietly confident profile.', 195.00, 'https://images.unsplash.com/photo-1552346154-21d32810aba3?auto=format&fit=crop&w=1200&q=85', 'Lifestyle', true, true, true, 'SD / 002'),
  ('Terrain Low', 'terrain-low', 'A versatile low cut built around durable materials and a grounded stance, designed for long days and repeat wear.', 182.00, 'https://images.unsplash.com/photo-1684918725924-ab55e49de549?q=80&w=627&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'Lifestyle', false, true, true, 'SD / 003'),
  ('Quiet Standard', 'quiet-standard', 'An all-day essential in softly grained leather, with tonal stitching and a clean cupsole that settles naturally into any rotation.', 148.00, 'https://images.unsplash.com/photo-1625860191460-10a66c7384fb?auto=format&fit=crop&w=1200&q=85', 'Lifestyle', true, true, false, 'SD / 004'),
  ('Cinder Track', 'cinder-track', 'A late-seventies running profile reworked in brushed suede and open mesh, finished with a cushioned heel and a quietly worn-in palette.', 172.00, 'https://images.unsplash.com/photo-1637437757614-6491c8e915b5?auto=format&fit=crop&w=1200&q=85', 'Running', true, true, false, 'SD / 005'),
  ('Aero Relay', 'aero-relay', 'A streamlined training silhouette with layered performance mesh, a stabilizing midfoot frame and responsive geometry for a quick daily stride.', 188.00, 'https://images.unsplash.com/photo-1496579538151-212636d0b01c?auto=format&fit=crop&w=1200&q=85', 'Running', true, true, false, 'SD / 006'),
  ('Meridian Court', 'meridian-court', 'A black leather court low-top with crisp white contrast, precise panel lines and a padded collar, balanced by a low-profile rubber sole.', 205.00, 'https://images.unsplash.com/photo-1543508282-6319a3e2621f?auto=format&fit=crop&w=1200&q=85', 'Lifestyle', true, true, false, 'SD / 007'),
  ('Night Archive', 'night-archive', 'A white leather low-top with measured black detailing and a softly sculpted sole, carrying a clean, graphic profile from day into evening.', 218.00, 'https://images.unsplash.com/photo-1780824946973-ab4e10ec90f6?auto=format&fit=crop&w=1200&q=85', 'Leather', true, true, false, 'SD / 008'),
  ('Ochre Assembly', 'ochre-assembly', 'Warm tobacco suede meets chalk leather in a considered panel construction, with waxed laces and a durable gum outsole.', 198.00, 'https://images.unsplash.com/photo-1617812865826-dc894cf651d0?auto=format&fit=crop&w=1200&q=85', 'Leather', false, true, true, 'SD / 009'),
  ('Studio High 02', 'studio-high-02', 'A confident high-top built from supple off-white leather, with a supportive ankle line and subtle hardware inspired by vintage court footwear.', 225.00, 'https://images.unsplash.com/photo-1598144112872-06be425d3c14?auto=format&fit=crop&w=1200&q=85', 'High-Top', true, true, false, 'SD / 010'),
  ('Afterhours High', 'afterhours-high', 'A deep charcoal canvas high-top with tonal eyelets, reinforced foxing and a cushioned footbed that softens its graphic silhouette.', 158.00, 'https://images.unsplash.com/photo-1565379793984-e65b51b33b37?auto=format&fit=crop&w=1200&q=85', 'High-Top', false, true, true, 'SD / 011'),
  ('Ridge Survey', 'ridge-survey', 'An outdoor-minded low cut pairing rugged tread with weather-ready overlays and breathable lining, balanced for city commutes and weekend trails.', 210.00, 'https://images.unsplash.com/photo-1718953323604-511b38655942?q=80&w=687&auto=format&fit=crop&ixlib=rb-4.1.0&ixid=NHwxMjA3fDA%3D', 'Outdoor', true, true, false, 'SD / 012'),
  ('Field Note 07', 'field-note-07', 'A limited trail release with a vivid red technical upper, weather-ready construction and confident tread for wet commutes and open paths.', 238.00, 'https://i.pinimg.com/1200x/f3/0b/ea/f30bea54a14c7f7ae7c633db8dc847fc.jpg', 'Outdoor', false, true, true, 'SD / 013'),
  ('Signal Red Edition', 'signal-red-edition', 'A numbered editorial release with vivid red accents over a light technical upper, balancing a fast visual read with considered everyday comfort.', 252.00, 'https://images.unsplash.com/photo-1739138054456-0aca1b90e4a9?auto=format&fit=crop&w=1200&q=85', 'Limited Edition', false, true, false, 'SD / 014'),
  ('Cloudline Mesh', 'cloudline-mesh', 'A clean white running silhouette with a breathable, layered upper and a springy, finely textured outsole for a light everyday stride.', 164.00, 'https://i.pinimg.com/736x/e1/4e/18/e14e18f0a78fdf4b41a4be77512a726f.jpg', 'Running', true, true, false, 'SD / 015')
